            function drawForeground() {
                const fgTop = H * 0.825;
                const fgBottom = H;

                const fgGrad = ctx.createLinearGradient(0, fgTop, 0, fgBottom);
                fgGrad.addColorStop(0, '#7a9a3a');
                fgGrad.addColorStop(0.15, '#6d8c32');
                fgGrad.addColorStop(0.5, '#5c7a28');
                fgGrad.addColorStop(1, '#4a6520');
                ctx.fillStyle = fgGrad;
                ctx.fillRect(0, fgTop, W, fgBottom - fgTop);

                // 草丛
                for (let x = 20; x < W; x += 35) {
                    const grassH = 12 + Math.sin(x * 0.7) * 8;
                    ctx.strokeStyle = '#8ab840';
                    ctx.lineWidth = 2;
                    ctx.lineCap = 'round';
                    for (let j = 0; j < 5; j++) {
                        const gx = x + j * 7;
                        const gh = grassH + Math.sin(j * 1.5) * 5;
                        ctx.beginPath();
                        ctx.moveTo(gx, fgTop);
                        ctx.quadraticCurveTo(gx + 3, fgTop - gh, gx + 1, fgTop - gh - 5);
                        ctx.stroke();
                    }
                }

                // 小野花
                for (let i = 0; i < 15; i++) {
                    const fx = (i * 211 + 40) % W;
                    const fy = fgTop + 8 + (i * 67) % (fgBottom - fgTop - 20);
                    ctx.fillStyle = '#fff';
                    ctx.beginPath();
                    ctx.arc(fx, fy, 3, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#ffe066';
                    ctx.beginPath();
                    ctx.arc(fx, fy, 1.5, 0, Math.PI * 2);
                    ctx.fill();
                }
            }

